import React, { useEffect, useState } from "react";
import axios from "axios";

function AdminDashboard() {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const res = await axios.get("http://localhost:5000/admin/users");
    setUsers(res.data);
  };

  const updateStatus = async (id, status) => {
    await axios.post("http://localhost:5000/admin/update-status", {
      id,
      status,
    });

    fetchUsers();
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin Dashboard</h2>

      {users.map((u) => (
        <div
          key={u.id}
          style={{
            border: "1px solid #ccc",
            margin: "10px",
            padding: "10px",
          }}
        >
          <p>Name: {u.name}</p>
          <p>Email: {u.email}</p>
          <p>Status: {u.payment_status}</p>

          {/* Screenshot */}
          {u.payment_screenshot && (
            <img
              src={`http://localhost:5000/uploads/${u.payment_screenshot}`}
              alt=""
              width="150"
            />
          )}

          <br />

          <button onClick={() => updateStatus(u.id, "approved")}>
            ✅ Approve
          </button>

          <button onClick={() => updateStatus(u.id, "rejected")}>
            ❌ Reject
          </button>
        </div>
      ))}
    </div>
  );
}

export default AdminDashboard;
